cat > /tmp/test-thresholds.mjs << 'EOF'
import { generateReport, runEvaluations } from '/private/tmp/100-tricks-runs/pilot-models/without/h2-eval-thresholds/r1/packages/frai-core/src/eval/index.js';

// Test 1: Report without thresholds should have no passed/thresholds fields
const evals1 = runEvaluations({
  outputs: ['Hello'],
  references: ['hello']
});
const report1 = generateReport({
  evaluations: evals1,
  outputsPath: '/tmp/outputs.json',
  referencesPath: '/tmp/refs.json'
});
console.log('Test 1 (no thresholds):', JSON.stringify({ passed: report1.passed, thresholds: report1.thresholds }, null, 2));

// Test 2: Report with passing thresholds
const evals2 = runEvaluations({
  outputs: ['Hello'],
  references: ['hello']
});
const report2 = generateReport({
  evaluations: evals2,
  outputsPath: '/tmp/outputs.json',
  referencesPath: '/tmp/refs.json',
  thresholds: { exact_match: 0.5 }
});
console.log('Test 2 (passing threshold):', JSON.stringify({ passed: report2.passed, thresholds: report2.thresholds }, null, 2));

// Test 3: Report with failing thresholds
const evals3 = runEvaluations({
  outputs: ['Hello'],
  references: ['hello']
});
const report3 = generateReport({
  evaluations: evals3,
  outputsPath: '/tmp/outputs.json',
  referencesPath: '/tmp/refs.json',
  thresholds: { exact_match: 0.99 }
});
console.log('Test 3 (failing threshold):', JSON.stringify({ passed: report3.passed, thresholds: report3.thresholds }, null, 2));

// Test 4: Report with threshold on metric without score
const evals4 = runEvaluations({
  outputs: ['Hello'],
  references: [] // No references, so exact_match will have score: null
});
const report4 = generateReport({
  evaluations: evals4,
  outputsPath: '/tmp/outputs.json',
  referencesPath: '/tmp/refs.json',
  thresholds: { exact_match: 0.5 }
});
console.log('Test 4 (threshold on null score):', JSON.stringify({ passed: report4.passed, thresholds: report4.thresholds }, null, 2));
EOF
node /tmp/test-thresholds.mjs
